import{_ as e,o as t,c as o,a0 as r}from"./chunks/framework.DqMqoJl9.js";const _=JSON.parse('{"title":"主流区块链","description":"","frontmatter":{},"headers":[],"relativePath":"blockChain/11-chain.md","filePath":"blockChain/11-chain.md","lastUpdated":1791573371000}'),p={name:"blockChain/11-chain.md"};function h(c,a,d,i,n,l){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="主流区块链" tabindex="-1">主流区块链 <a class="header-anchor" href="#主流区块链" aria-label="Permalink to &quot;主流区块链&quot;">​</a></h1><h2 id="_1-比特币-btc" tabindex="-1">1 比特币 BTC <a class="header-anchor" href="#_1-比特币-btc" aria-label="Permalink to &quot;1 比特币 BTC&quot;">​</a></h2><p>总体来看，比特币的市值和交易量远远超过其他区块链项目</p><p>比特币的发布时间为 2009 年 1 月 9 号，预计它的挖矿可以一直持续到 2140 年，发行总量收敛到 2100 万。比特币的出块时间是 10 分钟，出块时间是指全网平均产生一个区块的时间间隔</p><p>比特币是所有数字资产的始祖，这带来的效果就是：比特币的公众认可度非常高，纵然面临着矿池中心化的问题，但是公众依然非常信任比特币这种资产</p><p>比特币曾经面临过区块容量不足的问题，但随着隔离见证的生效，网络拥堵的问题缓解了很多</p><h2 id="_2-以太坊-eth" tabindex="-1">2 以太坊 ETH <a class="header-anchor" href="#_2-以太坊-eth" aria-label="Permalink to &quot;2 以太坊 ETH&quot;">​</a></h2><p>以太坊是一个区块链应用平台，它的极大创新在于它提供了智能合约这种可以自定义业务逻辑的工具，智能合约是一种可编程的合约，合约是由用户编写并且部署到区块链上的</p><p>这形成了一种良性循环，开发者使用智能合约的时候，发现的问题提交给以太坊开发者社区，社区改进智能合约的缺陷，新的开发者基于智能合约开发多样性的工具包，这种核心开发者与社区互动的良性循环是以太坊生态最重要的一部分</p><p>以太坊在 2014 年开始众筹，2015 年 3 月份正式运行，它采取的共识机制是 <code>PoW</code>，但根据核心团队公布的方案，后期会逐渐迁移到 <code>PoS</code> 共识算法。以太坊的总发行量是：6000 万 + 1872 万 / 年，目前的区块时间是 12 秒</p><p>同时我们从以太坊社区可以看到，以太坊绝大部分开发流程和智能合约都已经形成行业标准，比如常见的 <code>ERC20</code> 代币标准，<code>ERC725</code> 身份标准</p><p>而 <code>ERC20</code> 代币标准，则为智能合约指明了主要的业务方向：<strong>数字资产</strong>，有的叫智能资产，它们的含义差不多。以太坊 2017 价格大幅上涨，最直接的原因就是：<code>ERC20</code> 代币成为事实意义上的区块链标准资产</p><h2 id="_3-瑞波币" tabindex="-1">3 瑞波币 <a class="header-anchor" href="#_3-瑞波币" aria-label="Permalink to &quot;3 瑞波币&quot;">​</a></h2><p>瑞波币（Ripple）是一个比较另类的区块链项目，因为从本质上来说，它更像是一种支付结算协议，瑞波币不需要挖矿，它是通过一种叫 “Open Coin” 的算法，提供瑞波协议共识来达到记账的目的</p><p>瑞波币旨在为全球跨境机构提供了高效率的支付过程，提供较好的全球支付体验。因为涉及了机构之间的资产转移，瑞波币被设计成需要准入许可才能进入瑞波的支付网络，这一点有些像我们所说的联盟链</p><p>瑞波团队掌握了一半以上的瑞波币，所以瑞波币面临的币价被操纵的问题很严重。如果你是一个技术极客，那么你可以略过该项目。如果你想创建一个有关支付结算的区块链项目，那么一定要研究瑞波币</p><h2 id="_4-莱特币-ltc" tabindex="-1">4 莱特币 LTC <a class="header-anchor" href="#_4-莱特币-ltc" aria-label="Permalink to &quot;4 莱特币 LTC&quot;">​</a></h2><p>莱特币在技术上仅仅把比特币的挖矿算法修改成了 <code>Scrypt</code> 算法，<code>Scrypt</code> 算法是一个可参数化、可配置的挖矿算法，不过它依然没有防住专业矿机的出现。它的其他核心代码几乎与比特币保持一致</p><p>莱特币的崛起得益于良好的市场运作，从提供的功能来看，莱特币与比特币没有区别。那么说，为什么还要有莱特币呢？</p><p>是这样的，比特币扩容之争的核心焦点在是否使用“隔离见证”的方法，“隔离见证”虽然在比特币社区提出，但是第一个应用的地方是莱特币，即：莱特币作为比特币的先行者，它会替代比特币做一些具有实验性质的试运行</p><h2 id="_5-比特现金-bch" tabindex="-1">5 比特现金 BCH <a class="header-anchor" href="#_5-比特现金-bch" aria-label="Permalink to &quot;5 比特现金 BCH&quot;">​</a></h2><p>与比特币相比，比特现金仅仅是从区块容量上高于比特币，其他技术上的区别并不是很大</p><p>比特现金的诞生要从比特币扩容之争开始谈起，由于比特币的区块容量是 1MB，随着用户增多，交易愈发拥堵</p><p>所以围绕着提升网络容量，社区内部发生了分歧，“支持隔离见证” 与 “支持直接扩大区块尺寸” 分成了两派，这就是著名的扩容之争</p><p>比特币核心开发者们支持前者，矿工们支持后者，由于比特币核心开发者掌握了代码的控制权，但是矿工掌握了记账权，所以两权发生了分离，矿工索性一拍大腿，你不改代码，我花钱找人改，这就产生了比特现金</p><p>比特现金作为社区共识分裂的产物，体现了区块链开放共识的特点，你不支持我，我分分钟就可以独立出来</p><h2 id="_6-tether" tabindex="-1">6 Tether <a class="header-anchor" href="#_6-tether" aria-label="Permalink to &quot;6 Tether&quot;">​</a></h2><p>Tether 也是一个特殊的区块链项目，它为所有区块链资产提供了法币（主要是美元）兑换网关</p><p>Tether 又称 USDT，言外之意就是和美元一对一锚定，用户存入多少美元，就会产生多少 USDT 进入虚拟资产网络。USDT 可以直接在虚拟货币交易所与比特币等其他区块链资产进行交易</p><p>Tether 可以直接在二级市场流通，是数字货币交易市场重要的交易入口。另外，Tether 可能存在被冻结和没收的风险</p><h2 id="_7-匿名性区块链项目" tabindex="-1">7 匿名性区块链项目 <a class="header-anchor" href="#_7-匿名性区块链项目" aria-label="Permalink to &quot;7 匿名性区块链项目&quot;">​</a></h2><p>匿名性区块链项目是指：使用交易匿名技术，让公开可查询的交易内容变成私密的匿名性区块链项目。市值比较不错的有门罗币、达世币、Zcash 三种，它们分别使用了不同类型的匿名技术，为区块链技术的匿名特性发展做出了贡献</p><p>从需求上来看，这三种都是为了解决其他所有数字货币无法匿名的问题，因为从技术上看，比特币也好，以太坊也好，交易是可以被追踪的</p><p>所以以上三种区块链提供了不同程度的匿名，按照匿名程度分别是：达世币 &lt; 门罗币 &lt; Zcash。从市场认可度来看，门罗币的匿名性最为人们所认可</p>',34)])])}const b=e(p,[["render",h]]);export{_ as __pageData,b as default};
